// Demo program for: Zotero (citation manager)
// Public record -- Zotero, Mendeley, EndNote — the complete database of citation managers.
// Run it with: node demo.js   (works as-is on any PC with Node.js)
const record = {
  id: "JAH-CITE-000001",
  title: "Zotero",
  kind: "citation manager",
  developer: "Corporation for Digital Scholarship",
  platforms: "Windows, macOS, Linux, any modern web browser",
  license: "Open source"
};
function demo() {
  console.log("=== " + record.title + " ===");
